  ('vendor-adidas', 'Adidas Official Store', 'adidas-official', 'Through sport, we have the power to change lives. Samba, Gazelle, Ultraboost, and authentic athletic lifestyle sportswear.', 'https://images.unsplash.com/photo-1518002171953-a080ee817e1f?auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?auto=format&fit=crop&w=1200&q=80', 4.90, 4120, 0.07, 'active'),
  ('vendor-khaadi', 'Khaadi Retail Store', 'khaadi-official', 'Global Pakistani fashion house. Handcrafted artisan prêt, luxury unstitched fabrics, festive embroidered silks, and contemporary luxury womenswear.', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1200&q=80', 4.94, 3780, 0.09, 'active'),
  ('vendor-jdot', 'J. Junaid Jamshed', 'jdot-official', 'Heritage Pakistani clothing, luxury embroidered waistcoats, traditional kurtas, and artisan oriental perfumery.', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=1200&q=80', 4.91, 2960, 0.08, 'active'),
  ('vendor-national', 'National Foods Official', 'national-foods', 'Pioneers of authentic heritage spices, recipe mixes, mango pickles, and culinary staples since 1970. Pure flavors loved across 40+ countries.', 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1506368249639-73a05d6f6488?auto=format&fit=crop&w=1200&q=80', 4.96, 5890, 0.07, 'active'),
  ('vendor-shan', 'Shan Foods Global', 'shan-foods', 'Taste of heritage tradition. Authentic biryani, nihari, haleem, and gourmet recipe seasonings distributed globally.', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1514944298352-b88307db4106?auto=format&fit=crop&w=1200&q=80', 4.93, 4610, 0.07, 'active'),
  ('vendor-theordinary', 'The Ordinary Skincare', 'the-ordinary', 'Clinical formulations with integrity. Targeted serums, pure Hyaluronic Acid, Niacinamide, and scientific dermatological care.', 'https://images.unsplash.com/photo-1620916566398-39f1143ab7be?auto=format&fit=crop&w=200&q=80', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=1200&q=80', 4.93, 4120, 0.08, 'active')
